This section contains the contents of the repository's files.import React, { useEffect, useMemo, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { strings } from '@dologram/shared';
import { SearchField } from '../../../src/components/SearchField';
import { TopBar } from '../../../src/components/TopBar';
import { EmptyState } from '../../../src/components/EmptyState';
import { Icon } from '../../../src/components/Icon';
import { useAuth } from '../../../src/auth/AuthProvider';
import { useTheme } from '../../../src/theme/ThemeProvider';
import { textStyle } from '../../../src/theme/typography';
import { goBackOrReplace } from '../../../src/navigation/goBackOrReplace';
import { getLocalDatabase } from '../../../src/queue/db';
import { loadChatSnapshot, type ChatMessageItem } from '../../../src/chat/query';
import { attachmentLabel } from '../../../src/media/model';

function formatDate(value: string): string {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleDateString([], { month: 'short', day: 'numeric' });
}

export default function ChatSearchScreen() {
  const { chatId } = useLocalSearchParams<{ chatId: string }>();
  const router = useRouter();
  const theme = useTheme();
  const c = theme.colors;
  const { session } = useAuth();
  const [messages, setMessages] = useState<ChatMessageItem[]>([]);
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!chatId || !session?.user.id) return;
    let active = true;
    void getLocalDatabase().then((db) => loadChatSnapshot(db, chatId, session.user.id, { limit: 200 })).then((snapshot) => {
      if (active) setMessages(snapshot.messages.filter((message) => message.deletedAt === null));
    }).catch(() => undefined).finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [chatId, session?.user.id]);

  const matches = useMemo(() => {
    const normalized = query.trim().toLocaleLowerCase();
    if (!normalized) return [];
    return messages.filter((message) => {
      const content = `${message.senderName} ${message.content} ${message.attachments.map((item) => attachmentLabel(item.mediaType)).join(' ')}`;
      return content.toLocaleLowerCase().includes(normalized);
    }).reverse();
  }, [messages, query]);

  return (
    <View style={[styles.screen, { backgroundColor: c.bg.app }]}>
      <TopBar title={strings.chatInfo.search} onBack={() => goBackOrReplace(router, { pathname: '/chat/[chatId]/info', params: { chatId } })} />
      <View style={[styles.search, { padding: theme.space[4] }]}><SearchField placeholder="Search this chat" onSearch={setQuery} /></View>
      {loading ? <Text style={[textStyle(theme.typeTokens.bodyMd), styles.message, { color: c.text.secondary }]}>Loading messages…</Text> : query.trim().length === 0 ? <EmptyState iconName="action.search" title="Search this chat" message="Find messages, files and shared moments." /> : matches.length === 0 ? <EmptyState iconName="action.search" title="No results" message="Try a different word or phrase." /> : (
        <ScrollView keyboardShouldPersistTaps="handled">
          {matches.map((message) => <SearchResult key={message.messageId} message={message} onPress={() => router.replace({ pathname: '/chat/[chatId]', params: { chatId, focusMessageId: message.messageId } })} />)}
        </ScrollView>
      )}
    </View>
  );
}

function SearchResult({ message, onPress }: { message: ChatMessageItem; onPress: () => void }) {
  const theme = useTheme();
  const c = theme.colors;
  const summary = message.content || (message.attachments[0] ? attachmentLabel(message.attachments[0].mediaType) : strings.chat.attachmentOnly);
  return (
    <Pressable style={({ pressed }) => [styles.result, pressed && { backgroundColor: c.bg.pressed }]} onPress={onPress} accessibilityRole="button" accessibilityLabel={`${message.senderName || 'You'}: ${summary}`}>
      <View style={[styles.resultIcon, { backgroundColor: c.bg.surface }]}><Icon name={message.attachments.length > 0 ? 'action.file' : 'action.search'} size="sm" color={c.text.primary} accessibilityLabel="" /></View>
      <View style={styles.resultBody}><Text style={[textStyle(theme.typeTokens.labelMd), { color: c.text.primary }]}>{message.senderName || 'You'} · {formatDate(message.createdAt)}</Text><Text style={[textStyle(theme.typeTokens.bodyMd), { color: c.text.secondary }]} numberOfLines={2}>{summary}</Text></View>
      <Icon name="nav.forward" size="sm" color={c.text.muted} accessibilityLabel="" />
    </Pressable>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1 },
  search: { borderBottomWidth: StyleSheet.hairlineWidth },
  message: { padding: 20 },
  result: { minHeight: 72, flexDirection: 'row', alignItems: 'center', gap: 12, paddingHorizontal: 16, paddingVertical: 10 },
  resultIcon: { width: 40, height: 40, borderRadius: 20, alignItems: 'center', justifyContent: 'center' },
  resultBody: { flex: 1, gap: 3 },
});import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  ActivityIndicator, Animated, Easing, Keyboard, Pressable, SectionList, StyleSheet, Text, View,
  useWindowDimensions, type TextInput,
} from 'react-native';
import { useFocusEffect, useLocalSearchParams, useRouter } from 'expo-router';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import type { ChatListItem } from '@dologram/shared';
import { useAuth } from '../src/auth/AuthProvider';
import { useChatList } from '../src/chatList/useChatList';
import { Button, IconButton } from '../src/components/Button';
import { ChatRow } from '../src/components/ChatRow';
import { EmptyState, ErrorState } from '../src/components/EmptyState';
import { SearchField } from '../src/components/SearchField';
import { goBackOrReplace } from '../src/navigation/goBackOrReplace';
import { getLocalDatabase } from '../src/queue/db';
import { normalizeSearch, searchCachedMessages, type MessageMatch, type SearchCursor } from '../src/search/query';
import { subscribeCacheChange } from '../src/sync/cacheEvents';
import { useTheme } from '../src/theme/ThemeProvider';
import { textStyle } from '../src/theme/typography';

const SEARCH_BUTTON_WIDTH = 44;

export default function SearchScreen() {
  const { session } = useAuth();
  return session ? <AccountSearch key={session.user.id} userId={session.user.id} /> : null;
}

function AccountSearch({ userId }: { userId: string }) {
  const theme = useTheme();
  const router = useRouter();
  const { originX } = useLocalSearchParams<{ originX?: string }>();
  const insets = useSafeAreaInsets();
  const { width } = useWindowDimensions();
  const origin = Number(originX);
  const canExpand = Number.isFinite(origin) && !theme.reduceMotion;
  const progress = useRef(new Animated.Value(canExpand ? 0 : 1)).current;
  const input = useRef<TextInput>(null);
  const opening = useRef(false);
  const [query, setQuery] = useState('');
  const normalized = normalizeSearch(query);
  const { active, archived, ignored, loading, error, reload } = useChatList();
  const chats = useMemo(() => [...active, ...archived, ...ignored], [active, archived, ignored]);
  const chatIds = useMemo(() => JSON.stringify(chats.map((chat) => chat.chatId).sort()), [chats]);
  const duration = theme.duration('normal');
  const startLeft = Math.max(0, Math.min(width - SEARCH_BUTTON_WIDTH, origin - SEARCH_BUTTON_WIDTH / 2));

  useFocusEffect(useCallback(() => { opening.current = false; }, []));
  useEffect(() => {
    if (!canExpand) {
      progress.setValue(1);
      input.current?.focus();
      return;
    }
    const transition = Animated.timing(progress, {
      toValue: 1, duration, easing: Easing.out(Easing.cubic), useNativeDriver: false,
    });
    transition.start(({ finished }) => { if (finished) input.current?.focus(); });
    return () => transition.stop();
  }, [canExpand, duration, progress]);

  const openChat = useCallback((chatId: string, focusMessageId?: string) => {
    if (opening.current) return;
    opening.current = true;
    Keyboard.dismiss();
    router.push({
      pathname: '/chat/[chatId]',
      params: focusMessageId ? { chatId, focusMessageId } : { chatId },
    });
  }, [router]);

  return (
    <View style={styles.screen} accessibilityViewIsModal>
      <Animated.View
        pointerEvents="none"
        style={[StyleSheet.absoluteFill, { backgroundColor: theme.colors.bg.app, opacity: progress }]}
      />
      <View style={[styles.toolbar, { marginTop: insets.top }]}>
        <Animated.View style={{ marginLeft: insets.left + 4, opacity: progress }}>
          <IconButton iconName="nav.back" accessibilityLabel="Go back" onPress={() => goBackOrReplace(router)} />
        </Animated.View>
        <Animated.View style={[
          styles.field,
          {
            left: canExpand ? progress.interpolate({ inputRange: [0, 1], outputRange: [startLeft, insets.left + 52] }) : insets.left + 52,
            right: canExpand ? progress.interpolate({ inputRange: [0, 1], outputRange: [width - startLeft - SEARCH_BUTTON_WIDTH, insets.right + 12] }) : insets.right + 12,
          },
        ]}>
          <SearchField
            inputRef={input}
            placeholder="Search chats and messages"
            accessibilityLabel="Search chats and messages"
            autoCapitalize="none"
            autoCorrect={false}
            onSearch={setQuery}
            debounceMs={0}
          />
        </Animated.View>
      </View>
      <Animated.View style={[styles.screen, { opacity: progress, paddingBottom: insets.bottom }]}>
        {!normalized ? (
          <EmptyState iconName="action.search" title="Search DoloGram" message="Find conversations, messages and attachments." />
        ) : error && chats.length === 0 ? (
          <ErrorState title="Couldn't load chats" message="Try searching again." onRetry={() => void reload()} />
        ) : loading ? (
          <ActivityIndicator style={styles.loader} color={theme.colors.brand.primary} accessibilityLabel="Loading chats" />
        ) : (
          <SearchResults key={JSON.stringify([normalized, chatIds])} chats={chats} chatIds={chatIds} userId={userId} query={normalized} openChat={openChat} />
        )}
      </Animated.View>
    </View>
  );
}

type Result = { chat: ChatListItem } | { message: MessageMatch };

function SearchResults({ chats, chatIds, userId, query, openChat }: {
  chats: ChatListItem[];
  chatIds: string;
  userId: string;
  query: string;
  openChat: (chatId: string, messageId?: string) => void;
}) {
  const theme = useTheme();
  const chatsById = useMemo(() => new Map(chats.map((chat) => [chat.chatId, chat])), [chats]);
  const [results, setResults] = useState<MessageMatch[]>([]);
  const [next, setNext] = useState<SearchCursor | null>(null);
  const [request, setRequest] = useState<{ cursor: SearchCursor | null }>({ cursor: null });
  const [settled, setSettled] = useState<typeof request | null>(null);
  const [failed, setFailed] = useState(false);
  const loading = settled !== request;

  useEffect(() => subscribeCacheChange(() => setRequest({ cursor: null })), []);
  useEffect(() => {
    const controller = new AbortController();
    const search = async () => {
      try {
        const page = chatIds === '[]' ? { matches: [], next: null } : await searchCachedMessages(
          await getLocalDatabase(), userId, chatIds, query, request.cursor, controller.signal,
        );
        if (controller.signal.aborted) return;
        setResults((previous) => request.cursor ? [...previous, ...page.matches] : page.matches);
        setNext(page.next);
        setFailed(false);
      } catch {
        if (!controller.signal.aborted) setFailed(true);
      } finally {
        if (!controller.signal.aborted) setSettled(request);
      }
    };
    const timer = setTimeout(() => void search(), request.cursor ? 0 : 150);
    return () => { clearTimeout(timer); controller.abort(); };
  }, [chatIds, query, request, userId]);

  const matchingChats = chats.filter((chat) => normalizeSearch(chat.title).includes(query));
  const messages = results.filter((message) => chatsById.has(message.chatId));
  const sections: { title: string; data: Result[] }[] = [
    { title: 'Chats', data: matchingChats.map((chat) => ({ chat })) },
    { title: 'Messages', data: messages.map((message) => ({ message })) },
  ].filter((section) => section.data.length > 0);

  return (
    <SectionList<Result>
      sections={sections}
      keyboardShouldPersistTaps="handled"
      keyboardDismissMode="on-drag"
      stickySectionHeadersEnabled={false}
      keyExtractor={(item) => 'chat' in item ? `chat:${item.chat.chatId}` : item.message.messageId}
      renderSectionHeader={({ section }) => (
        <Text accessibilityRole="header" style={[styles.section, textStyle(theme.typeTokens.titleSm), { color: theme.colors.text.primary }]}>
          {section.title}
        </Text>
      )}
      renderItem={({ item }) => {
        if ('chat' in item) return <ChatRow item={item.chat} onPress={openChat} />;
        const { message } = item;
        const title = chatsById.get(message.chatId)?.title ?? '';
        const date = new Date(message.createdAt).toLocaleDateString([], { dateStyle: 'medium' });
        return (
          <Pressable
            accessibilityRole="button"
            accessibilityLabel={`${title}, ${message.sender}, ${date}, ${message.preview}`}
            onPress={() => openChat(message.chatId, message.messageId)}
            style={({ pressed }) => [styles.message, pressed && { backgroundColor: theme.colors.bg.pressed }]}
          >
            <Text numberOfLines={1} style={[textStyle(theme.typeTokens.labelMd), { color: theme.colors.text.primary }]}>
              {title} · {message.sender} · {date}
            </Text>
            <Text numberOfLines={2} style={[textStyle(theme.typeTokens.bodyMd), { color: theme.colors.text.secondary }]}>
              {message.preview}
            </Text>
          </Pressable>
        );
      }}
      contentContainerStyle={sections.length === 0 ? styles.emptyList : undefined}
      ListEmptyComponent={loading || failed ? null : (
        <EmptyState iconName="action.search" title="No results" message="Try a different word or phrase." />
      )}
      ListFooterComponent={loading ? (
        <ActivityIndicator style={styles.loader} color={theme.colors.brand.primary} accessibilityLabel="Searching messages" />
      ) : failed ? (
        <View style={styles.footer}>
          <Text accessibilityRole="alert" style={[textStyle(theme.typeTokens.bodyMd), { color: theme.colors.error.text }]}>
            {"Couldn't search messages."}
          </Text>
          <Button variant="secondary" label="Retry" onPress={() => setRequest({ ...request })} />
        </View>
      ) : next ? (
        <View style={styles.footer}>
          <Button variant="secondary" label="Show more messages" onPress={() => setRequest({ cursor: next })} />
        </View>
      ) : null}
    />
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1 },
  toolbar: { height: 56, justifyContent: 'center', alignItems: 'flex-start' },
  field: { position: 'absolute', top: 8, overflow: 'hidden', borderRadius: 24 },
  emptyList: { flexGrow: 1 },
  loader: { marginVertical: 24 },
  section: { paddingHorizontal: 16, paddingTop: 16, paddingBottom: 8 },
  message: { minHeight: 68, paddingVertical: 10, paddingHorizontal: 16, gap: 4 },
  footer: { padding: 16, gap: 8, alignItems: 'center' },
});/**
 * CMP-03: Search field — height 40, full radius, debounced filtering.
 * 12.5, D-95
 */
import React, { useEffect, useRef, useState } from 'react';
import {
  TextInput,
  View,
  Pressable,
  StyleSheet,
  type TextInputProps,
} from 'react-native';
import { useTheme } from '../theme/ThemeProvider';
import { textStyle } from '../theme/typography';
import { Icon } from './Icon';

export interface SearchFieldProps extends Omit<TextInputProps, 'onChangeText'> {
  /** Called ~150 ms after the user stops typing. */
  onSearch: (query: string) => void;
  debounceMs?: number;
  inputRef?: React.Ref<TextInput>;
}

export function SearchField({
  onSearch,
  debounceMs = 150,
  placeholder = 'Search',
  inputRef,
  ...inputProps
}: SearchFieldProps) {
  const theme = useTheme();
  const c = theme.colors;
  const [value, setValue] = useState('');
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, []);

  const handleChange = (text: string) => {
    setValue(text);
    if (timerRef.current) clearTimeout(timerRef.current);
    if (debounceMs === 0) onSearch(text);
    else timerRef.current = setTimeout(() => onSearch(text), debounceMs);
  };

  const handleClear = () => {
    setValue('');
    if (timerRef.current) clearTimeout(timerRef.current);
    onSearch('');
  };

  return (
    <View
      style={[
        styles.container,
        {
          height: 40,
          borderRadius: theme.radius.full,
          backgroundColor: c.bg.surface,
          paddingHorizontal: theme.space[3],
        },
      ]}
    >
      <Icon name="action.search" size="sm" color={c.text.muted} />

      <TextInput
        ref={inputRef}
        style={[
          styles.input,
          { ...textStyle(theme.typeTokens.bodyMd), color: c.text.primary },
        ]}
        value={value}
        onChangeText={handleChange}
        placeholder={placeholder}
        placeholderTextColor={c.text.muted}
        returnKeyType="search"
        clearButtonMode="never"
        accessibilityRole="search"
        {...inputProps}
      />

      {value.length > 0 ? (
        <Pressable
          onPress={handleClear}
          accessibilityLabel="Clear search"
          accessibilityRole="button"
          style={styles.clearButton}
          hitSlop={8}
        >
          <Icon name="nav.close" size="sm" color={c.text.muted} />
        </Pressable>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  input: { flex: 1 },
  clearButton: { padding: 2 },
});import { DatabaseSync } from 'node:sqlite';
import type { SQLiteDatabase } from 'expo-sqlite';
import { normalizeSearch, searchCachedMessages } from '../query';

let sqlite: DatabaseSync;
let db: SQLiteDatabase;

beforeEach(() => {
  sqlite = new DatabaseSync(':memory:');
  sqlite.exec(`
    CREATE TABLE cache_messages (
      message_id TEXT PRIMARY KEY, chat_id TEXT, sender_id TEXT, seq INTEGER,
      created_at TEXT, deleted_at TEXT, payload TEXT
    );
    CREATE TABLE cache_chat_members (chat_id TEXT, user_id TEXT, nickname TEXT);
    CREATE TABLE cache_profiles (user_id TEXT, display_name TEXT);
    CREATE TABLE cache_message_media (message_id TEXT, payload TEXT);
    INSERT INTO cache_chat_members VALUES ('chat', 'me', NULL), ('chat', 'other', 'José');
  `);
  db = {
    getAllAsync: async (sql: string, params: string[]) => sqlite.prepare(sql).all(...params),
  } as unknown as SQLiteDatabase;
});

afterEach(() => sqlite.close());

function addMessage(id: string, content: string, options: {
  chatId?: string; senderId?: string; deleted?: boolean; seq?: number;
} = {}) {
  sqlite.prepare('INSERT INTO cache_messages VALUES (?, ?, ?, ?, ?, ?, ?)').run(
    id, options.chatId ?? 'chat', options.senderId ?? 'me', options.seq ?? 1,
    '2026-11-11T00:00:00Z', options.deleted ? '2026-11-11T01:00:00Z' : null,
    JSON.stringify({ content }),
  );
}

function search(query: string, cursor: Parameters<typeof searchCachedMessages>[4] = null) {
  return searchCachedMessages(db, 'me', '["chat"]', normalizeSearch(query), cursor, new AbortController().signal);
}

test('searches beyond the newest 200 rows and preserves tied-date pagination', async () => {
  for (let index = 0; index < 260; index++) {
    addMessage(String(index).padStart(3, '0'), index < 35 ? 'Needle' : 'Unrelated');
  }
  const first = await search('needle');
  expect(first.matches).toHaveLength(30);
  expect(first.matches[0].messageId).toBe('034');
  expect(first.next).toBeTruthy();
  const second = await search('needle', first.next);
  expect(second.matches).toHaveLength(5);
  expect(second.next).toBeNull();
  expect(new Set([...first.matches, ...second.matches].map((message) => message.messageId)).size).toBe(35);
});

test('excludes deleted messages, other accounts, and hidden conversations', async () => {
  addMessage('valid', 'needle');
  addMessage('deleted', 'needle', { deleted: true });
  addMessage('foreign', 'needle', { chatId: 'foreign' });
  sqlite.prepare('INSERT INTO cache_chat_members VALUES (?, ?, NULL)').run('foreign', 'someone-else');
  addMessage('hidden', 'needle', { chatId: 'hidden' });
  sqlite.prepare('INSERT INTO cache_chat_members VALUES (?, ?, NULL)').run('hidden', 'me');
  const result = await searchCachedMessages(db, 'me', '["chat","foreign"]', 'needle', null, new AbortController().signal);
  expect(result.matches.map((message) => message.messageId)).toEqual(['valid']);
});

test('normalizes Unicode and treats SQL metacharacters literally', async () => {
  addMessage('unicode', 'ＣＡＦÉ');
  addMessage('literal', "100%_ ' OR 1=1 --");
  expect((await search('café')).matches.map((message) => message.messageId)).toEqual(['unicode']);
  expect((await search("%_ ' OR 1=1 --")).matches.map((message) => message.messageId)).toEqual(['literal']);
});

test('matches sender nicknames and live attachment types', async () => {
  addMessage('nickname', 'hello', { senderId: 'other' });
  addMessage('file', '');
  addMessage('removed-file', '');
  sqlite.prepare('INSERT INTO cache_message_media VALUES (?, ?)').run('file', JSON.stringify({ media_type: 'file', deleted_at: null }));
  sqlite.prepare('INSERT INTO cache_message_media VALUES (?, ?)').run('removed-file', JSON.stringify({ media_type: 'file', deleted_at: '2026-11-11' }));
  expect((await search('josé')).matches.map((message) => message.messageId)).toEqual(['nickname']);
  const files = await search('file');
  expect(files.matches.map((message) => message.messageId)).toEqual(['file']);
  expect(files.matches[0].preview).toBe('File');
});

test('stops a cancelled search and returns no matches for an empty query', async () => {
  const controller = new AbortController();
  controller.abort();
  const getAll = jest.spyOn(db, 'getAllAsync');
  await searchCachedMessages(db, 'me', '["chat"]', 'hello', null, controller.signal);
  await search('');
  expect(getAll).not.toHaveBeenCalled();
